impl CaptureForm {
    /// A body with its required fields.
    pub fn new(file: Vec<crate::client::FilePart>, kind: impl Into<CaptureFormKind>) -> Self {
        Self {
            captured_at: None,
            document_type: None,
            file,
            kind: kind.into(),
            party_id: None,
            side: None,
        }
    }

    /// Optional: when each file was captured, RFC 3339, one per file in the order of the files.
    pub fn captured_at(mut self, captured_at: Vec<String>) -> Self {
        self.captured_at = Some(captured_at);
        self
    }

    /// Required for a document, refused for anything else.
    pub fn document_type(mut self, document_type: impl Into<CaptureFormDocumentType>) -> Self {
        self.document_type = Some(document_type.into());
        self
    }

    /// The party captured. Empty is the case's primary party.
    pub fn party_id(mut self, party_id: impl Into<String>) -> Self {
        self.party_id = Some(party_id.into());
        self
    }

    /// Required for a document, refused for anything else.
    pub fn side(mut self, side: impl Into<CaptureFormSide>) -> Self {
        self.side = Some(side.into());
        self
    }

    /// The form's fields, in the order of the contract: a list as one part
    /// per item.
    pub(crate) fn parts(&self) -> Vec<(&'static str, crate::client::Part)> {
        let mut parts = Vec::new();
        for each in self.captured_at.iter().flatten() {
            parts.push(("captured_at", crate::client::Part::Text(each.clone())));
        }
        if let Some(value) = &self.document_type {
            parts.push(("document_type", crate::client::Part::Text(value.as_str().to_owned())));
        }
        for each in &self.file {
            parts.push(("file", crate::client::Part::File(each.clone())));
        }
        parts.push(("kind", crate::client::Part::Text(self.kind.as_str().to_owned())));
        if let Some(value) = &self.party_id {
            parts.push(("party_id", crate::client::Part::Text(value.clone())));
        }
        if let Some(value) = &self.side {
            parts.push(("side", crate::client::Part::Text(value.as_str().to_owned())));
        }
        parts
    }
}

